'use client';
import { useQuery } from '@tanstack/react-query';
import { Bar, BarChart, CartesianGrid, Cell, Legend, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { api } from '@/lib/api';
import { useAuth } from '@/lib/providers';
import { useChartColors } from '@/lib/use-chart-colors';
import type { Dashboard } from '@/lib/types';
import { PageHeader } from '@/components/shared/page-header';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Progress } from '@/components/ui/progress';
import { StatusBadge } from '@/components/shared/status-badge';
import { Skeleton } from '@/components/ui/skeleton';
import { ErrorState } from '@/components/ui/error-state';
import { formatDate, formatMoney, titleCase } from '@/lib/utils';
export default function AnalyticsPage() {
  const { org, isClient } = useAuth();
  const c = useChartColors();
  const tooltipStyle = { background: c.surface, border: `1px solid ${c.grid}`, borderRadius: 8, fontSize: 12, color: c.text } as const;
  const q = useQuery({ queryKey: ['dashboard', org?.id], queryFn: () => api<Dashboard>('/analytics/dashboard'), enabled: !!org });
  if (q.isLoading) return <div className="space-y-4"><Skeleton className="h-9 w-64" /><div className="grid gap-4 lg:grid-cols-2"><Skeleton className="h-80" /><Skeleton className="h-80" /></div></div>;
  if (q.isError) return <ErrorState error={q.error} onRetry={() => q.refetch()} />;
  const d = q.data!;
  return <div><PageHeader title="Analytics" description="Database-backed reporting. No hardcoded demonstration numbers." />
    <div className="grid gap-6 lg:grid-cols-2">
      <Card><CardHeader><CardTitle>Revenue by month</CardTitle><CardDescription>Succeeded payments, trailing six months</CardDescription></CardHeader><CardContent className="h-64 sm:h-72"><ResponsiveContainer><LineChart data={d.revenueByMonth}><CartesianGrid stroke={c.grid} vertical={false} /><XAxis dataKey="month" tick={{ fontSize: 11, fill: c.axis }} tickLine={false} stroke={c.grid} /><YAxis tick={{ fontSize: 11, fill: c.axis }} tickLine={false} stroke={c.grid} tickFormatter={(v) => `$${v / 1000}k`} /><Tooltip formatter={(v) => formatMoney(Number(v))} contentStyle={tooltipStyle} labelStyle={{ color: c.axis }} /><Line type="monotone" dataKey="revenue" stroke={c.accent} strokeWidth={2} dot={{ r: 3 }} /></LineChart></ResponsiveContainer></CardContent></Card>
      <Card><CardHeader><CardTitle>Tasks by status</CardTitle><CardDescription>Visible projects</CardDescription></CardHeader><CardContent className="h-64 sm:h-72">{d.tasksByStatus.length ? <ResponsiveContainer><PieChart><Pie data={d.tasksByStatus} dataKey="count" nameKey="status" innerRadius={55} outerRadius={90} paddingAngle={2}>{d.tasksByStatus.map((_, i) => <Cell key={i} fill={c.status[d.tasksByStatus[i].status] ?? c.series[i % c.series.length]} />)}</Pie><Tooltip contentStyle={tooltipStyle} labelStyle={{ color: c.axis }} /><Legend formatter={(v) => titleCase(String(v))} wrapperStyle={{ fontSize: 11, color: c.axis }} /></PieChart></ResponsiveContainer> : <p className="text-sm text-ink-muted">No tasks.</p>}</CardContent></Card>
      {!isClient && <Card><CardHeader><CardTitle>Team workload</CardTitle><CardDescription>Open, high-priority, and overdue tasks</CardDescription></CardHeader><CardContent className="h-64 sm:h-72">{d.workload.length ? <ResponsiveContainer><BarChart data={d.workload}><CartesianGrid stroke={c.grid} vertical={false} /><XAxis dataKey="name" tick={{ fontSize: 11, fill: c.axis }} tickLine={false} stroke={c.grid} /><YAxis allowDecimals={false} tick={{ fontSize: 11, fill: c.axis }} tickLine={false} stroke={c.grid} /><Tooltip contentStyle={tooltipStyle} labelStyle={{ color: c.axis }} /><Legend wrapperStyle={{ fontSize: 11, color: c.axis }} /><Bar dataKey="openTasks" name="Open" fill={c.accent} radius={[4, 4, 0, 0]} /><Bar dataKey="urgent" name="High/urgent" fill={c.warning} radius={[4, 4, 0, 0]} /><Bar dataKey="overdue" name="Overdue" fill={c.danger} radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer> : <p className="text-sm text-ink-muted">No team data.</p>}</CardContent></Card>}
      <Card><CardHeader><CardTitle>Outstanding invoices</CardTitle><CardDescription>{formatMoney(d.kpis.outstanding)} across unpaid sent invoices</CardDescription></CardHeader><CardContent><div className="grid grid-cols-2 gap-4"><div className="rounded-md border border-border bg-sunken/50 p-4"><p className="text-xs text-ink-muted">Outstanding</p><p className="mt-1 font-mono text-2xl font-medium">{formatMoney(d.kpis.outstanding)}</p></div><div className="rounded-md border border-border bg-sunken/50 p-4"><p className="text-xs text-ink-muted">Overdue invoices</p><p className="mt-1 font-mono text-2xl font-medium text-destructive">{d.kpis.overdueInvoices}</p></div><div className="rounded-md border border-border bg-sunken/50 p-4"><p className="text-xs text-ink-muted">Active clients</p><p className="mt-1 font-mono text-2xl font-medium">{d.kpis.activeClients} / {d.kpis.totalClients}</p></div><div className="rounded-md border border-border bg-sunken/50 p-4"><p className="text-xs text-ink-muted">Open tickets</p><p className="mt-1 font-mono text-2xl font-medium">{d.kpis.openTickets}</p></div></div></CardContent></Card>
    </div>
    <Card className="mt-6"><CardHeader><CardTitle>Project performance</CardTitle><CardDescription>Completion, overdue tasks, and budget</CardDescription></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Project</TableHead><TableHead className="hidden md:table-cell">Client</TableHead><TableHead>Status</TableHead><TableHead>Progress</TableHead><TableHead className="hidden sm:table-cell">Overdue</TableHead><TableHead className="hidden lg:table-cell">Due</TableHead>{!isClient && <TableHead className="text-end">Budget</TableHead>}</TableRow></TableHeader><TableBody>{d.projectPerformance.map((p) => <TableRow key={p.id}><TableCell className="font-medium">{p.name}</TableCell><TableCell className="hidden text-sm md:table-cell">{p.client}</TableCell><TableCell><StatusBadge status={p.status} /></TableCell><TableCell><div className="flex items-center gap-2"><Progress value={p.progress} className="w-24" /><span className="text-xs">{p.progress}%</span></div></TableCell><TableCell className={`hidden font-mono sm:table-cell ${p.overdue ? 'font-medium text-danger' : 'text-ink-muted'}`}>{p.overdue}</TableCell><TableCell className="hidden text-sm lg:table-cell">{formatDate(p.dueDate)}</TableCell>{!isClient && <TableCell className="text-end font-mono">{formatMoney(p.budget)}</TableCell>}</TableRow>)}</TableBody></Table></CardContent></Card>
  </div>;
}

