    <Dialog open={settingsOpen} onOpenChange={setSettingsOpen}><DialogContent><DialogHeader><DialogTitle>Project settings</DialogTitle></DialogHeader><form method="post" onSubmit={settingsForm.handleSubmit((d) => saveSettings.mutate(d))} className="space-y-4"><FormField label="Name" required><Input {...settingsForm.register('name')} /></FormField><FormField label="Description"><Textarea {...settingsForm.register('description')} /></FormField><div className="grid grid-cols-2 gap-4"><FormField label="Status"><Select value={settingsForm.watch('status')} onValueChange={(v) => settingsForm.setValue('status', v as z.infer<typeof settingsSchema>['status'])}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{['PLANNED', 'ACTIVE', 'ON_HOLD', 'COMPLETED', 'ARCHIVED'].map((s) => <SelectItem key={s} value={s}>{titleCase(s)}</SelectItem>)}</SelectContent></Select></FormField><FormField label="Budget"><Input type="number" min={0} {...settingsForm.register('budget')} /></FormField></div><div className="grid grid-cols-2 gap-4"><FormField label="Start date"><Input type="date" {...settingsForm.register('startDate')} /></FormField><FormField label="Due date"><Input type="date" {...settingsForm.register('dueDate')} /></FormField></div><DialogFooter><Button type="submit" loading={saveSettings.isPending}>Save</Button></DialogFooter></form></DialogContent></Dialog>
  </div>;
}

