'use client';

import * as React from 'react';
import { Suspense } from 'react';
import Link from 'next/link';
import { useRouter, useSearchParams } from 'next/navigation';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { CheckCircle2 } from 'lucide-react';
import { authApi } from '@/lib/api';
import { useAuth } from '@/lib/providers';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { FormField } from '@/components/shared/form-field';
import { AuthPanel } from '@/components/layout/auth-panel';
import { useHydrated } from '@/lib/use-hydrated';

const schema = z.object({
  name: z.string().min(2, 'Enter your name').max(80),
  password: z.string().min(10, 'At least 10 characters').regex(/[A-Za-z]/, 'Include a letter').regex(/[0-9]/, 'Include a number'),
});

function AcceptForm() {
  const token = useSearchParams().get('token') || '';
  const router = useRouter();
  const { refresh } = useAuth();
  const [status, setStatus] = React.useState<'idle' | 'submitting' | 'success'>('idle');
  const hydrated = useHydrated();
  const [formError, setFormError] = React.useState<string | null>(null);
  const { register, handleSubmit, formState: { errors } } = useForm<z.infer<typeof schema>>({ resolver: zodResolver(schema) });

  const onSubmit = async (data: z.infer<typeof schema>) => {
    if (status !== 'idle') return;
    setStatus('submitting');
    setFormError(null);
    try {
      await authApi.accept({ token, ...data });
      setStatus('success');
      await refresh();
      router.replace('/dashboard');
      router.refresh();
    } catch (error) {
      setStatus('idle');
      setFormError(
        error instanceof Error && error.message
          ? error.message
          : 'This invitation is no longer valid. Ask the workspace owner to send a new one.',
      );
    }
  };

  if (status === 'success') {
    return (
      <div role="status" aria-live="polite" className="grid place-items-center gap-3 py-16 text-center">
        <CheckCircle2 className="h-8 w-8 text-success" aria-hidden />
        <p className="text-base font-medium">Invitation accepted</p>
        <p className="text-sm text-ink-muted">Opening your workspace…</p>
      </div>
    );
  }

  return (
    <div>
      <h1 className="text-2xl font-semibold tracking-tight">Accept invitation</h1>
      <p className="mt-1.5 text-sm text-ink-muted">
        Create your account to join the workspace. If this email already has an account, enter its password to confirm
        ownership.
      </p>
      {!token ? (
        <p className="mt-6 rounded-md border border-danger/30 bg-danger/5 px-3.5 py-3 text-sm">
          This link is missing its invitation token. Ask the workspace owner to resend the invitation.
        </p>
      ) : (
        <>
          {formError && (
            <div role="alert" className="mt-5 rounded-md border border-danger/30 bg-danger/5 px-3.5 py-3 text-sm">
              {formError}
            </div>
          )}
          <form method="post" onSubmit={handleSubmit(onSubmit)} aria-busy={status === 'submitting'} className="mt-6 space-y-4" noValidate>
            <FormField label="Your name" error={errors.name?.message}>
              <Input autoComplete="name" disabled={status === 'submitting'} {...register('name')} />
            </FormField>
            <FormField label="Password" error={errors.password?.message} hint="At least 10 characters, with a letter and a number.">
              <Input type="password" autoComplete="new-password" disabled={status === 'submitting'} {...register('password')} />
            </FormField>
            <Button type="submit" className="h-11 w-full" disabled={!hydrated} loading={status === 'submitting'}>
              {status === 'submitting' ? 'Joining workspace…' : 'Join workspace'}
            </Button>
          </form>
        </>
      )}
      <p className="mt-6 text-sm text-ink-muted">
        <Link href="/login" className="font-medium text-accent underline-offset-4 hover:underline">
          Already have an account? Sign in
        </Link>
      </p>
    </div>
  );
}

export default function AcceptPage() {
  return (
    <AuthPanel>
      <Suspense>
        <AcceptForm />
      </Suspense>
    </AuthPanel>
  );
}

src/app/forgot-password/page.tsx:
'use client';

import * as React from 'react';
import Link from 'next/link';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { MailCheck } from 'lucide-react';
import { authApi } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { FormField } from '@/components/shared/form-field';
import { AuthPanel } from '@/components/layout/auth-panel';
import { useHydrated } from '@/lib/use-hydrated';

const schema = z.object({ email: z.string().email('Enter a valid email address') });
type Result = { message: string; developmentResetUrl?: string; emailDelivered: boolean };

export default function ForgotPage() {
  const [result, setResult] = React.useState<Result | null>(null);
  const [failed, setFailed] = React.useState(false);
  const hydrated = useHydrated();
  const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm<z.infer<typeof schema>>({ resolver: zodResolver(schema) });

  const onSubmit = async (data: z.infer<typeof schema>) => {
    setFailed(false);
    try {
      setResult(await authApi.forgot(data.email));
    } catch {
      setFailed(true);
    }
  };

  return (
    <AuthPanel>
      {result ? (
        <div role="status" aria-live="polite" className="space-y-4">
          <MailCheck className="h-7 w-7 text-accent" strokeWidth={1.5} aria-hidden />
          <h1 className="text-xl font-semibold tracking-tight">Check your email</h1>
          <p className="text-sm text-ink-muted">{result.message}</p>
          {!result.emailDelivered && (
            <p className="rounded-md border border-warning/30 bg-warning/10 px-3.5 py-3 text-sm text-warning">
              Email delivery is not configured on this deployment, so no message was sent.
            </p>
          )}
          {result.developmentResetUrl && (
            <div className="rounded-md border border-border bg-sunken/60 p-3.5 text-sm">
              <p className="font-medium">Development recovery link</p>
              <Link
                className="mt-1 block break-all font-mono text-xs text-accent underline-offset-4 hover:underline"
                href={result.developmentResetUrl.replace(/^https?:\/\/[^/]+/, '')}
              >
                {result.developmentResetUrl}
              </Link>
            </div>
          )}
          <Link href="/login" className="inline-block text-sm font-medium text-accent underline-offset-4 hover:underline">
            Back to sign in
          </Link>
        </div>
      ) : (
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Reset your password</h1>
          <p className="mt-1.5 text-sm text-ink-muted">
            Enter your email and we will send a recovery link if the account exists.
          </p>
          {failed && (
            <div role="alert" className="mt-5 rounded-md border border-danger/30 bg-danger/5 px-3.5 py-3 text-sm">
              Could not reach the recovery service. Check your connection and try again.
            </div>
          )}
          <form method="post" onSubmit={handleSubmit(onSubmit)} className="mt-6 space-y-4" noValidate>
            <FormField label="Email" error={errors.email?.message}>
              <Input type="email" inputMode="email" autoComplete="email" autoCapitalize="none" {...register('email')} />
            </FormField>
            <Button type="submit" className="h-11 w-full" disabled={!hydrated} loading={isSubmitting}>
              {isSubmitting ? 'Sending link…' : 'Send recovery link'}
            </Button>
          </form>
          <Link href="/login" className="mt-6 inline-block text-sm text-accent underline-offset-4 hover:underline">
            Back to sign in
          </Link>
        </div>
      )}
    </AuthPanel>
  );
}

src/app/globals.css:
@tailwind base;
@tailwind components;
@tailwind utilities;

/*
 * AgencyOS design tokens.
 *
 * Values are space-separated RGB channels so Tailwind can apply opacity modifiers
 * (`bg-accent/10`) without a second palette. Components reference semantic names only —
 * never a raw hex, never a visual name like `gray-300`.
 *
 * Neutrals are tinted a few degrees toward the pine accent so surfaces feel related to the
 * brand rather than borrowed from a default grey ramp.
 */
@layer base {
  :root {
    /* Surfaces */
    --bg: 247 247 245;
    --surface: 255 255 255;
    --raised: 255 255 255;
    --sunken: 239 239 236;
    --border: 226 227 222;
    --border-strong: 203 205 198;

    /* Text — muted clears 4.5:1 on both bg and surface; faint is for non-essential hints only */
    --text: 25 28 26;
    --text-muted: 90 96 92;
    --text-faint: 135 141 137;

    /* Brand */
    --accent: 20 98 79;
    --accent-hover: 15 78 63;
    --accent-contrast: 255 255 255;
    --accent-soft: 230 240 236;

    /* Semantic — these mean their meaning, never decoration */
    --success: 27 122 75;
    --warning: 154 91 0;
    --danger: 178 58 46;
    --danger-contrast: 255 255 255;
    --info: 35 95 168;

    /* Navigation rail */
    --rail: 23 26 24;
    --rail-text: 221 226 222;
    --rail-muted: 142 150 145;
    --rail-border: 42 47 44;

    /* Shape — different jobs, different radii */
    --r-xs: 3px;
    --r-sm: 5px;
    --r-md: 8px;
    --r-lg: 14px;

    /* Elevation, tinted from the ink hue rather than pure black */
    --shadow-1: 0 1px 2px rgb(25 28 26 / 0.06);
    --shadow-2: 0 4px 12px rgb(25 28 26 / 0.08);
    --shadow-3: 0 12px 32px rgb(25 28 26 / 0.14);

    /* Motion */
    --ease-out: cubic-bezier(0.2, 0.8, 0.2, 1);
    --ease-in: cubic-bezier(0.4, 0, 1, 1);
    --dur-fast: 120ms;
    --dur-base: 200ms;
    --dur-slow: 320ms;

    /* Layout variables owned by the shell. Content padding, sticky bars and toast offsets
       all read these, so the bottom bar can never cover content or a toast. */
    --sidebar-w: 272px;
    --bottom-nav-h: 0px;

    color-scheme: light;
  }

  :root[data-theme='dark'] {
    --bg: 20 22 26;
    --surface: 27 30 35;
    --raised: 35 39 46;
    --sunken: 16 18 22;
    --border: 44 49 58;
    --border-strong: 61 68 79;

    --text: 232 234 231;
    --text-muted: 154 162 160;
    --text-faint: 110 118 121;

    /* Re-tuned for dark, not inverted: lighter and less saturated so large areas don't vibrate */
    --accent: 79 191 160;
    --accent-hover: 107 208 180;
    --accent-contrast: 8 32 26;
    --accent-soft: 18 48 42;

    --success: 79 194 135;
    --warning: 224 164 69;
    --danger: 240 119 106;
    --danger-contrast: 32 12 10;
    --info: 111 166 238;

    --rail: 16 18 22;
    --rail-text: 221 226 222;
    --rail-muted: 142 150 145;
    --rail-border: 38 43 51;

    /* In dark mode elevation reads as a lighter surface, so shadows stay shallow */
    --shadow-1: 0 1px 2px rgb(0 0 0 / 0.4);
    --shadow-2: 0 4px 12px rgb(0 0 0 / 0.45);
    --shadow-3: 0 12px 32px rgb(0 0 0 / 0.55);

    color-scheme: dark;
  }

  * {
    border-color: rgb(var(--border));
  }

  html {
    -webkit-text-size-adjust: 100%;
  }

  /* Below the tablet breakpoint the phone bottom bar owns the bottom of the viewport. */
  @media (max-width: 767px) {
    :root {
      --bottom-nav-h: calc(56px + env(safe-area-inset-bottom, 0px));
    }
  }

  body {
    background-color: rgb(var(--bg));
    color: rgb(var(--text));
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  h1, h2, h3, h4 {
    text-wrap: balance;
    letter-spacing: -0.011em;
  }

  p {
    text-wrap: pretty;
  }

  /* Every figure that aligns in a column or changes in place uses tabular numerals */
  .tnum,
  table,
  [data-figure] {
    font-variant-numeric: tabular-nums;
  }

  ::selection {
    background-color: rgb(var(--accent) / 0.18);
  }

  /* A visible, high-contrast ring on every interactive element. Never removed without a replacement. */
  :focus-visible {
    outline: 2px solid rgb(var(--accent));
    outline-offset: 2px;
    border-radius: var(--r-xs);
  }

  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }

  @media (forced-colors: active) {
    :focus-visible {
      outline: 2px solid Highlight;
    }
  }
}

@layer components {
  .focus-ring {
    @apply focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent;
  }

  /* Skeletons mirror the real layout; one low-contrast sweep, static under reduced motion. */
  .skeleton {
    position: relative;
    overflow: hidden;
    border-radius: var(--r-sm);
    background-color: rgb(var(--sunken));
  }
  .skeleton::after {
    content: '';
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background-image: linear-gradient(90deg, transparent, rgb(var(--text) / 0.06), transparent);
    animation: skeleton-sweep 1.6s var(--ease-out) infinite;
  }
  @media (prefers-reduced-motion: reduce) {
    .skeleton::after {
      animation: none;
    }
  }

  /* Scrollable but chrome-free: the sidebar must not show a native scrollbar on any OS. */
  .no-scrollbar {
    scrollbar-width: none;
    -ms-overflow-style: none;
    overscroll-behavior: contain;
  }
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }

  /* Hidden scroll still has to be discoverable, so the edges fade out. */
  .scroll-fade {
    mask-image: linear-gradient(to bottom, transparent 0, #000 12px, #000 calc(100% - 20px), transparent 100%);
  }

  .scrollbar-thin {
    scrollbar-width: thin;
    scrollbar-color: rgb(var(--border-strong)) transparent;
  }
  .scrollbar-thin::-webkit-scrollbar {
    height: 8px;
    width: 8px;
  }
  .scrollbar-thin::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background-color: rgb(var(--border-strong));
  }
  .scrollbar-thin::-webkit-scrollbar-track {
    background: transparent;
  }

  .skip-link {
    position: absolute;
    inset-inline-start: 12px;
    inset-block-start: -60px;
    z-index: 60;
    border-radius: var(--r-sm);
    background-color: rgb(var(--accent));
    color: rgb(var(--accent-contrast));
    padding: 10px 16px;
    font-size: 14px;
    font-weight: 500;
    transition: inset-block-start var(--dur-base) var(--ease-out);
  }
  .skip-link:focus {
    inset-block-start: 12px;
  }
}

@keyframes skeleton-sweep {
  to {
    transform: translateX(100%);
  }
}

