'use client';

import * as React from 'react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useQuery } from '@tanstack/react-query';
import * as Dialog from '@radix-ui/react-dialog';
import { ArrowLeft, Bell, Menu, PanelLeftOpen, X } from 'lucide-react';
import { api } from '@/lib/api';
import { useAuth } from '@/lib/providers';
import { cn } from '@/lib/utils';
import { CLIENT_NAV, AGENCY_NAV, isActivePath, visibleNav } from '@/lib/nav';
import { SIDEBAR_RAIL, type SidebarState } from '@/lib/sidebar';
import type { Notification } from '@/lib/types';
import { Avatar } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { Tooltip, TooltipProvider } from '@/components/ui/tooltip';
import { ThemeToggle } from '@/components/theme/theme';
import { AppFooter } from '@/components/layout/app-footer';
import { BottomNav } from '@/components/layout/bottom-nav';
import { Sidebar } from '@/components/layout/sidebar';
import { useSidebarResize } from '@/components/layout/use-sidebar-resize';

function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(false);
  React.useEffect(() => {
    const mq = window.matchMedia(query);
    const update = () => setMatches(mq.matches);
    update();
    mq.addEventListener('change', update);
    return () => mq.removeEventListener('change', update);
  }, [query]);
  return matches;
}

/**
 * The one layout shell. It owns sidebar width and collapse state, which navigation is mounted
 * at the current breakpoint, the top bar, and the CSS variables that content padding and toast
 * offsets read. Pages never reimplement navigation.
 *
 * Before hydration both navs are in the tree but CSS-gated, so the first paint is correct on
 * every device; after hydration only the active one stays mounted.
 */
export function AppShell({ children, initialSidebar }: { children: React.ReactNode; initialSidebar: SidebarState }) {
  const { user, org, role, isLoading, isClient, isManagement } = useAuth();
  const pathname = usePathname();
  const router = useRouter();
  const [mounted, setMounted] = React.useState(false);
  const [drawerOpen, setDrawerOpen] = React.useState(false);
  const tabletUp = useMediaQuery('(min-width: 768px)');
  const desktop = useMediaQuery('(min-width: 1024px)');
  const resize = useSidebarResize(initialSidebar);

  React.useEffect(() => setMounted(true), []);
  React.useEffect(() => {
    if (!isLoading && !user) router.replace(`/login?next=${encodeURIComponent(pathname)}`);
  }, [isLoading, user, router, pathname]);
  React.useEffect(() => setDrawerOpen(false), [pathname]);

  const notifications = useQuery({
    queryKey: ['notifications', org?.id],
    queryFn: () => api<Notification[]>('/notifications?unread=true'),
    enabled: !!org,
    refetchInterval: 60_000,
  });
  const unread = notifications.data?.length ?? 0;

  const items = visibleNav(isClient ? CLIENT_NAV : AGENCY_NAV, { isManagement });

  // Content offset and toast clearance are derived here, once, as CSS variables.
  const sidebarWidth = !tabletUp ? 0 : desktop ? (resize.collapsed ? SIDEBAR_RAIL : resize.width) : SIDEBAR_RAIL;
  React.useEffect(() => {
    document.documentElement.style.setProperty('--sidebar-w', `${sidebarWidth}px`);
  }, [sidebarWidth]);

  if (isLoading || !user) return <ShellSkeleton />;

  const activeItem = items.find((item) => isActivePath(pathname, item.href));
  const deep = Boolean(activeItem && pathname !== activeItem.href);

  const showSidebar = !mounted || tabletUp;
  const showBottomNav = !mounted || !tabletUp;

  return (
    <TooltipProvider delayDuration={300} skipDelayDuration={150}>
      <div className="min-h-dvh">
        <a href="#main" className="skip-link">
          Skip to content
        </a>

        {showSidebar && (
          <aside
            className="fixed inset-y-0 start-0 z-30 hidden md:block"
            style={{ width: desktop ? (resize.collapsed ? SIDEBAR_RAIL : resize.width) : SIDEBAR_RAIL }}
          >
            <Sidebar
              items={items}
              collapsed={!desktop || resize.collapsed}
              unread={unread}
              width={resize.width}
              dragging={resize.dragging}
              onToggle={() => (desktop ? resize.toggle() : setDrawerOpen(true))}
              handleProps={desktop ? resize.handleProps : undefined}
            />
          </aside>
        )}

        {/* Tablet: the rail stays put and the full sidebar opens over the content. */}
        <Dialog.Root open={drawerOpen} onOpenChange={setDrawerOpen}>
          <Dialog.Portal>
            <Dialog.Overlay className="fixed inset-0 z-overlay bg-ink/50 motion-safe:animate-fade-in lg:hidden" />
            <Dialog.Content
              className="fixed inset-y-0 start-0 z-modal w-[272px] shadow-3 motion-safe:animate-fade-in lg:hidden"
              aria-describedby={undefined}
            >
              <Dialog.Title className="sr-only">Navigation</Dialog.Title>
              <Sidebar items={items} collapsed={false} unread={unread} onToggle={() => setDrawerOpen(false)} onNavigate={() => setDrawerOpen(false)} overlay />
              <Dialog.Close asChild>
                <button
                  type="button"
                  aria-label="Close navigation"
                  className="absolute end-3 top-4 inline-flex h-9 w-9 items-center justify-center rounded-sm text-rail-muted hover:bg-white/10 hover:text-white"
                >
                  <X className="h-5 w-5" aria-hidden />
                </button>
              </Dialog.Close>
            </Dialog.Content>
          </Dialog.Portal>
        </Dialog.Root>

        <div
          className={cn('flex min-h-dvh min-w-0 flex-col', !resize.dragging && 'transition-[margin] duration-base ease-out')}
          style={{ marginInlineStart: mounted ? 'var(--sidebar-w)' : undefined }}
        >
          <header className="sticky top-0 z-20 flex h-14 shrink-0 items-center gap-2 border-b border-border bg-surface/90 px-3 backdrop-blur supports-[backdrop-filter]:bg-surface/75 sm:h-16 sm:px-6">
            {tabletUp && !desktop ? (
              <Button variant="ghost" size="icon" onClick={() => setDrawerOpen(true)} aria-label="Open navigation">
                <Menu aria-hidden />
              </Button>
            ) : null}
            {!tabletUp && deep ? (
              <Button variant="ghost" size="icon" onClick={() => router.back()} aria-label="Back">
                <ArrowLeft aria-hidden />
              </Button>
            ) : null}

            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-medium sm:hidden">{activeItem?.label ?? org?.name}</p>
              <p className="hidden truncate text-sm text-ink-muted sm:block">
                <span className="text-ink">{org?.name}</span>
                <span className="mx-2 text-ink-faint">/</span>
                <span className="capitalize">{role?.toLowerCase().replace('_', ' ')}</span>
              </p>
            </div>

            <div className="flex items-center gap-1.5">
              {desktop && <ThemeToggle compact className="me-1" />}
              <Tooltip content="Notifications" side="bottom">
                <Button variant="ghost" size="icon" asChild className="relative">
                  <Link href="/notifications" aria-label={`Notifications${unread ? `, ${unread} unread` : ''}`}>
                    <Bell aria-hidden />
                    {unread > 0 && (
                      <span className="absolute end-1 top-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-accent px-1 text-[10px] font-semibold tabular-nums text-accent-contrast">
                        {unread > 9 ? '9+' : unread}
                      </span>
                    )}
                  </Link>
                </Button>
              </Tooltip>
              {desktop && !resize.collapsed ? null : desktop ? (
                <Tooltip content="Expand sidebar (⌘B)" side="bottom">
                  <Button variant="ghost" size="icon" onClick={resize.toggle} aria-label="Expand sidebar">
                    <PanelLeftOpen aria-hidden />
                  </Button>
                </Tooltip>
              ) : null}
              <Avatar name={user.name} />
            </div>
          </header>

          <main id="main" className="min-w-0 flex-1 px-4 pb-[calc(var(--bottom-nav-h)+1.5rem)] pt-5 sm:px-6 sm:pt-6 lg:px-8 lg:pb-8">
            {children}
          </main>

          <AppFooter className="pb-[calc(var(--bottom-nav-h)+1.25rem)] lg:pb-5" />
        </div>

        {showBottomNav && <BottomNav items={items} unread={unread} />}
      </div>
    </TooltipProvider>
  );
}

/** Mirrors the real shell so the swap to content causes no layout shift. */
function ShellSkeleton() {
  return (
    <div className="min-h-dvh" aria-busy="true">
      <div className="fixed inset-y-0 start-0 hidden w-[272px] border-e border-rail-border bg-rail md:block" aria-hidden />
      <div className="md:ms-[272px]">
        <div className="flex h-14 items-center gap-3 border-b border-border px-4 sm:h-16 sm:px-6">
          <Skeleton className="h-4 w-40" />
          <Skeleton className="ms-auto h-8 w-8 rounded-full" />
        </div>
        <div className="space-y-6 px-4 pt-6 sm:px-6 lg:px-8">
          <Skeleton className="h-8 w-56" />
          <Skeleton className="h-24 w-full" />
          <div className="grid gap-6 lg:grid-cols-3">
            <Skeleton className="h-72 lg:col-span-2" />
            <Skeleton className="h-72" />
          </div>
        </div>
      </div>
      <span className="sr-only" role="status">
        Loading your workspace
      </span>
    </div>
  );
}

src/components/layout/bottom-nav.tsx:
'use client';

import * as React from 'react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import * as Dialog from '@radix-ui/react-dialog';
import { Building2, Check, LogOut, MoreHorizontal, X } from 'lucide-react';
import { useAuth } from '@/lib/providers';
import { cn } from '@/lib/utils';
import { ADMIN_NAV, FOOTER_NAV, NAV_SECTIONS, isActivePath, type NavItem } from '@/lib/nav';
import { Avatar } from '@/components/ui/avatar';
import { ThemeToggle } from '@/components/theme/theme';

/**
 * The phone navigation: four destinations plus "More".
 *
 * Everything that doesn't fit lives in a bottom sheet rather than a hamburger, so the four
 * things people actually open stay one tap away. The bar owns `--bottom-nav-h`; content
 * padding and the toast offset both read that variable, so nothing ever sits behind it.
 */
export function BottomNav({ items, unread }: { items: NavItem[]; unread: number }) {
  const pathname = usePathname();
  const [moreOpen, setMoreOpen] = React.useState(false);
  const { isClient, isSuperAdmin } = useAuth();

  const slots = items.filter((item) => item.bottom).slice(0, 4);
  const rest = items.filter((item) => !slots.includes(item));
  const footerItems = FOOTER_NAV.filter((item) => !(isClient && item.href === '/settings'));
  const hiddenUnread = [...rest, ...footerItems].some((item) => item.badge === 'notifications' && unread > 0);
  const moreActive = moreOpen || [...rest, ...footerItems].some((item) => isActivePath(pathname, item.href));

  React.useEffect(() => setMoreOpen(false), [pathname]);

  return (
    <>
      <nav
        aria-label="Primary"
        className="fixed inset-x-0 bottom-0 z-sticky border-t border-border bg-surface/95 pb-[env(safe-area-inset-bottom)] backdrop-blur supports-[backdrop-filter]:bg-surface/85 lg:hidden"
      >
        <ul className="mx-auto grid max-w-lg grid-cols-5">
          {slots.map((item) => {
            const active = isActivePath(pathname, item.href);
            const Icon = item.icon;
            return (
              <li key={item.href}>
                <Link
                  href={item.href}
                  aria-current={active ? 'page' : undefined}
                  onClick={(e) => {
                    // Tapping where you already are takes you back to the top of the section.
                    if (active) {
                      e.preventDefault();
                      window.scrollTo({ top: 0, behavior: 'smooth' });
                    }
                  }}
                  className={cn(
                    'relative flex h-14 min-w-12 flex-col items-center justify-center gap-0.5 text-[11px] transition-colors duration-fast',
                    active ? 'font-medium text-accent' : 'text-ink-muted',
                  )}
                >
                  {active && <span aria-hidden className="absolute inset-x-4 top-0 h-0.5 rounded-full bg-accent" />}
                  <Icon className="h-6 w-6" strokeWidth={active ? 2 : 1.5} aria-hidden />
                  <span className="truncate px-1">{item.shortLabel ?? item.label}</span>
                </Link>
              </li>
            );
          })}
          <li>
            <button
              type="button"
              onClick={() => setMoreOpen(true)}
              aria-haspopup="dialog"
              aria-expanded={moreOpen}
              className={cn(
                'relative flex h-14 w-full min-w-12 flex-col items-center justify-center gap-0.5 text-[11px] transition-colors duration-fast',
                moreActive ? 'font-medium text-accent' : 'text-ink-muted',
              )}
            >
              <span className="relative">
                <MoreHorizontal className="h-6 w-6" strokeWidth={moreActive ? 2 : 1.5} aria-hidden />
                {hiddenUnread && (
                  <span aria-hidden className="absolute -end-0.5 -top-0.5 h-2 w-2 rounded-full bg-accent ring-2 ring-surface" />
                )}
              </span>
              <span>More</span>
              {hiddenUnread && <span className="sr-only">{unread} unread notifications</span>}
            </button>
          </li>
        </ul>
      </nav>

      <MoreSheet open={moreOpen} onOpenChange={setMoreOpen} items={rest} footerItems={footerItems} unread={unread} showAdmin={isSuperAdmin && !isClient} />
    </>
  );
}

function MoreSheet({
  open,
  onOpenChange,
  items,
  footerItems,
  unread,
  showAdmin,
}: {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  items: NavItem[];
  footerItems: NavItem[];
  unread: number;
  showAdmin: boolean;
}) {
  const pathname = usePathname();
  const router = useRouter();
  const { user, org, organizations, role, logout, switchOrg } = useAuth();

  const row = (item: NavItem) => {
    const active = isActivePath(pathname, item.href);
    const Icon = item.icon;
    const count = item.badge === 'notifications' ? unread : 0;
    return (
      <li key={item.href}>
        <Link
          href={item.href}
          aria-current={active ? 'page' : undefined}
          className={cn(
            'flex min-h-12 items-center gap-3 rounded-md px-3 text-sm transition-colors duration-fast',
            active ? 'bg-accent-soft font-medium text-accent' : 'text-ink hover:bg-sunken',
          )}
        >
          <Icon className="h-5 w-5 shrink-0" strokeWidth={1.5} aria-hidden />
          {item.label}
          {count > 0 && (
            <span className="ms-auto rounded-xs bg-accent px-1.5 py-0.5 text-[11px] font-semibold tabular-nums text-accent-contrast">
              {count > 9 ? '9+' : count}
            </span>
          )}
        </Link>
      </li>
    );
  };

  return (
    <Dialog.Root open={open} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 z-overlay bg-ink/40 motion-safe:animate-fade-in" />
        <Dialog.Content
          className={cn(
            'fixed inset-x-0 bottom-0 z-modal max-h-[85dvh] overflow-y-auto rounded-t-lg border-t border-border bg-surface pb-[max(1rem,env(safe-area-inset-bottom))] shadow-3',
            'motion-safe:animate-rise-in',
          )}
        >
          <div className="sticky top-0 z-10 bg-surface px-4 pb-2 pt-3">
            <div aria-hidden className="mx-auto mb-3 h-1 w-9 rounded-full bg-border-strong" />
            <div className="flex items-center justify-between">
              <Dialog.Title className="text-base font-semibold">More</Dialog.Title>
              <Dialog.Close asChild>
                <button
                  type="button"
                  aria-label="Close"
                  className="inline-flex h-11 w-11 items-center justify-center rounded-sm text-ink-muted hover:bg-sunken hover:text-ink"
                >
                  <X className="h-5 w-5" aria-hidden />
                </button>
              </Dialog.Close>
            </div>
            <Dialog.Description className="sr-only">Remaining destinations, workspace, and appearance</Dialog.Description>
          </div>

          <div className="space-y-5 px-4 pb-4">
            {NAV_SECTIONS.map((section) => {
              const group = items.filter((item) => item.section === section);
              if (group.length === 0) return null;
              return (
                <section key={section}>
                  <h3 className="px-3 pb-1 text-[11px] font-medium text-ink-faint">{section}</h3>
                  <ul className="space-y-0.5">{group.map(row)}</ul>
                </section>
              );
            })}

            <section>
              <h3 className="px-3 pb-1 text-[11px] font-medium text-ink-faint">Account</h3>
              <ul className="space-y-0.5">
                {footerItems.map(row)}
                {showAdmin && row(ADMIN_NAV)}
              </ul>
            </section>

            <section className="rounded-md border border-border p-3">
              <h3 className="pb-2 text-[11px] font-medium text-ink-faint">Workspace</h3>
              <ul className="space-y-0.5">
                {organizations.map((o) => (
                  <li key={o.id}>
                    <button
                      type="button"
                      onClick={() => {
                        switchOrg(o.id);
                        onOpenChange(false);
                      }}
                      className={cn(
                        'flex min-h-12 w-full items-center gap-3 rounded-md px-3 text-start text-sm transition-colors duration-fast',
                        o.id === org?.id ? 'bg-accent-soft font-medium text-accent' : 'text-ink hover:bg-sunken',
                      )}
                    >
                      <Building2 className="h-5 w-5 shrink-0" strokeWidth={1.5} aria-hidden />
                      <span className="min-w-0 flex-1 truncate">{o.name}</span>
                      {o.id === org?.id && <Check className="h-4 w-4 shrink-0" aria-hidden />}
                    </button>
                  </li>
                ))}
                <li>
                  <button
                    type="button"
                    onClick={() => {
                      onOpenChange(false);
                      router.push('/settings?newOrg=1');
                    }}
                    className="flex min-h-12 w-full items-center gap-3 rounded-md px-3 text-start text-sm text-ink-muted transition-colors duration-fast hover:bg-sunken hover:text-ink"
                  >
                    <Building2 className="h-5 w-5 shrink-0" strokeWidth={1.5} aria-hidden />
                    Create workspace
                  </button>
                </li>
              </ul>
            </section>

            <div className="flex items-center justify-between gap-3">
              <span className="text-sm text-ink-muted">Appearance</span>
              <ThemeToggle />
            </div>

            <div className="flex items-center gap-3 border-t border-border pt-4">
              <Avatar name={user?.name ?? ''} />
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium">{user?.name}</p>
                <p className="truncate text-xs capitalize text-ink-muted">{role?.toLowerCase().replace('_', ' ')}</p>
              </div>
              <button
                type="button"
                onClick={logout}
                className="inline-flex min-h-11 items-center gap-2 rounded-sm border border-border px-3 text-sm text-ink-muted transition-colors duration-fast hover:bg-sunken hover:text-ink"
              >
                <LogOut className="h-4 w-4" aria-hidden />
                Sign out
              </button>
            </div>
          </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

src/components/layout/sidebar.tsx:
'use client';

import * as React from 'react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { Building2, Check, ChevronDown, LogOut, PanelLeftClose, PanelLeftOpen } from 'lucide-react';
import { useAuth } from '@/lib/providers';
import { cn } from '@/lib/utils';
import { ADMIN_NAV, FOOTER_NAV, NAV_SECTIONS, isActivePath, type NavItem } from '@/lib/nav';
import { SIDEBAR_MAX, SIDEBAR_MIN } from '@/lib/sidebar';
import { Avatar } from '@/components/ui/avatar';
import { Tooltip } from '@/components/ui/tooltip';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

function NavLink({
  item,
  collapsed,
  unread,
  onNavigate,
}: {
  item: NavItem;
  collapsed: boolean;
  unread: number;
  onNavigate?: () => void;
}) {
  const pathname = usePathname();
  const active = isActivePath(pathname, item.href);
  const count = item.badge === 'notifications' ? unread : 0;
  const Icon = item.icon;

  const link = (
    <Link
      href={item.href}
      onClick={onNavigate}
      aria-current={active ? 'page' : undefined}
      className={cn(
        'group relative flex h-10 items-center gap-3 rounded-md px-3 text-sm transition-colors duration-fast',
        'text-rail-muted hover:bg-white/[0.06] hover:text-rail-text',
        active && 'bg-white/[0.08] font-medium text-white',
        collapsed && 'justify-center px-0',
      )}
    >
      {active && <span aria-hidden className="absolute inset-y-2 start-0 w-0.5 rounded-full bg-accent" />}
      <span className="relative shrink-0">
        <Icon className="h-5 w-5" strokeWidth={1.5} aria-hidden />
        {collapsed && count > 0 && (
          <span aria-hidden className="absolute -end-1 -top-1 h-2 w-2 rounded-full bg-accent ring-2 ring-rail" />
        )}
      </span>
      <span className={cn('truncate', collapsed && 'sr-only')}>{item.label}</span>
      {!collapsed && count > 0 && (
        <span className="ms-auto rounded-xs bg-accent px-1.5 py-0.5 text-[11px] font-semibold tabular-nums text-accent-contrast">
          {count > 9 ? '9+' : count}
        </span>
      )}
      {collapsed && count > 0 && <span className="sr-only">{count} unread</span>}
    </Link>
  );

  return (
    <Tooltip content={item.label} side="right" disabled={!collapsed}>
      {link}
    </Tooltip>
  );
}

export interface SidebarProps {
  items: NavItem[];
  collapsed: boolean;
  unread: number;
  onToggle: () => void;
  onNavigate?: () => void;
  /** Overlay mode is the tablet/mobile drawer: always expanded, with its own close affordance. */
  overlay?: boolean;
  handleProps?: React.HTMLAttributes<HTMLDivElement>;
  dragging?: boolean;
  width?: number;
}

export function Sidebar({
  items,
  collapsed,
  unread,
  onToggle,
  onNavigate,
  overlay = false,
  handleProps,
  dragging = false,
  width,
}: SidebarProps) {
  const { user, org, organizations, role, logout, switchOrg, isSuperAdmin, isClient } = useAuth();
  const router = useRouter();
  const rail = collapsed && !overlay;

  const footerItems = FOOTER_NAV.filter((item) => !(isClient && item.href === '/settings'));

  return (
    <div className="relative flex h-dvh flex-col border-e border-rail-border bg-rail [color-scheme:dark]">
      {/* Fixed: identity + workspace switcher */}
      <div className={cn('flex h-16 shrink-0 items-center gap-2.5 border-b border-rail-border px-4', rail && 'justify-center px-0')}>
        <span
          aria-hidden
          className="flex h-8 w-8 shrink-0 items-center justify-center rounded-sm bg-accent font-mono text-sm font-semibold text-accent-contrast"
        >
          A
        </span>
        {!rail && <span className="truncate text-[15px] font-semibold tracking-tight text-white">AgencyOS</span>}
        {!overlay && !rail && (
          <Tooltip content="Collapse sidebar (⌘B)" side="bottom">
            <button
              type="button"
              onClick={onToggle}
              className="ms-auto inline-flex h-8 w-8 items-center justify-center rounded-sm text-rail-muted transition-colors duration-fast hover:bg-white/[0.06] hover:text-white"
              aria-label="Collapse sidebar"
            >
              <PanelLeftClose className="h-4 w-4" strokeWidth={1.5} aria-hidden />
            </button>
          </Tooltip>
        )}
      </div>

      <div className={cn('shrink-0 px-3 py-3', rail && 'px-2')}>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button
              type="button"
              className={cn(
                'flex w-full items-center gap-2 rounded-md border border-rail-border bg-white/[0.04] px-3 py-2 text-start text-sm text-rail-text transition-colors duration-fast hover:bg-white/[0.08]',
                rail && 'h-10 justify-center px-0',
              )}
              aria-label={`Workspace: ${org?.name ?? 'none selected'}. Change workspace`}
            >
              {rail ? (
                <span aria-hidden className="font-mono text-xs font-semibold uppercase text-accent">
                  {(org?.name ?? 'A').slice(0, 2)}
                </span>
              ) : (
                <>
                  <Building2 className="h-4 w-4 shrink-0 text-rail-muted" strokeWidth={1.5} aria-hidden />
                  <span className="min-w-0 flex-1 truncate">{org?.name ?? 'Select workspace'}</span>
                  <ChevronDown className="h-4 w-4 shrink-0 text-rail-muted" aria-hidden />
                </>
              )}
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start" className="w-64">
            <DropdownMenuLabel>Workspaces</DropdownMenuLabel>
            {organizations.map((o) => (
              <DropdownMenuItem key={o.id} onSelect={() => switchOrg(o.id)}>
                <span className="flex-1 truncate">{o.name}</span>
                <span className="text-xs capitalize text-ink-muted">{o.role.toLowerCase().replace('_', ' ')}</span>
                {o.id === org?.id && <Check className="h-4 w-4 text-accent" aria-hidden />}
              </DropdownMenuItem>
            ))}
            <DropdownMenuSeparator />
            <DropdownMenuItem onSelect={() => router.push('/settings?newOrg=1')}>
              <Building2 aria-hidden />
              Create workspace
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      {/* Scrolls, but never shows a scrollbar. The edge fade signals that more items exist. */}
      <nav
        aria-label="Primary"
        className="no-scrollbar scroll-fade min-h-0 flex-1 overflow-y-auto px-3 py-1"
      >
        {NAV_SECTIONS.map((section) => {
          const group = items.filter((item) => item.section === section);
          if (group.length === 0) return null;
          return (
            <div key={section} className="mb-1">
              {rail ? (
                <div aria-hidden className="mx-2 my-2 border-t border-rail-border first:hidden" />
              ) : (
                <p className="px-3 pb-1 pt-3 text-[11px] font-medium text-rail-muted/80">{section}</p>
              )}
              <ul className="space-y-0.5">
                {group.map((item) => (
                  <li key={item.href}>
                    <NavLink item={item} collapsed={rail} unread={unread} onNavigate={onNavigate} />
                  </li>
                ))}
              </ul>
            </div>
          );
        })}
        {isSuperAdmin && !isClient && (
          <div className="mt-1">
            {rail ? (
              <div aria-hidden className="mx-2 my-2 border-t border-rail-border" />
            ) : (
              <p className="px-3 pb-1 pt-3 text-[11px] font-medium text-rail-muted/80">Platform</p>
            )}
            <NavLink item={ADMIN_NAV} collapsed={rail} unread={0} onNavigate={onNavigate} />
          </div>
        )}
      </nav>

      {/* Pinned: never clipped by the scrolling region above, at any height or width. */}
      <div className="shrink-0 border-t border-rail-border p-3">
        <ul className="space-y-0.5">
          {footerItems.map((item) => (
            <li key={item.href}>
              <NavLink item={item} collapsed={rail} unread={unread} onNavigate={onNavigate} />
            </li>
          ))}
        </ul>
        {rail ? (
          <div className="mt-2 flex flex-col items-center gap-1">
            <Tooltip content="Expand sidebar (⌘B)" side="right">
              <button
                type="button"
                onClick={onToggle}
                aria-label="Expand sidebar"
                className="inline-flex h-10 w-10 items-center justify-center rounded-md text-rail-muted transition-colors duration-fast hover:bg-white/[0.06] hover:text-white"
              >
                <PanelLeftOpen className="h-5 w-5" strokeWidth={1.5} aria-hidden />
              </button>
            </Tooltip>
            <UserMenu user={user} role={role} logout={logout} rail />
          </div>
        ) : (
          <div className="mt-2 flex items-center gap-3 px-1 pt-2">
            <UserMenu user={user} role={role} logout={logout} />
          </div>
        )}
      </div>

      {/* Resize handle: 12px hit area, 1px visible line, keyboard operable. */}
      {!overlay && handleProps && (
        <div
          role="separator"
          aria-orientation="vertical"
          aria-label="Resize sidebar"
          aria-valuemin={SIDEBAR_MIN}
          aria-valuemax={SIDEBAR_MAX}
          aria-valuenow={width}
          tabIndex={0}
          {...handleProps}
          className="group absolute inset-y-0 -end-1.5 z-10 hidden w-3 cursor-col-resize touch-none lg:block"
        >
          <span
            aria-hidden
            className={cn(
              'absolute inset-y-0 start-1/2 w-px transition-colors duration-fast',
              dragging ? 'bg-accent' : 'bg-transparent group-hover:bg-accent group-focus-visible:bg-accent',
            )}
          />
        </div>
      )}
    </div>
  );
}

function UserMenu({
  user,
  role,
  logout,
  rail = false,
}: {
  user: { name: string; email: string } | null;
  role: string | null;
  logout: () => void;
  rail?: boolean;
}) {
  const router = useRouter();
  if (!user) return null;
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button
          type="button"
          className={cn(
            'flex min-w-0 items-center gap-3 rounded-md p-1 text-start transition-colors duration-fast hover:bg-white/[0.06]',
            rail ? 'h-10 w-10 justify-center' : 'flex-1',
          )}
          aria-label={`Account: ${user.name}`}
        >
          <Avatar name={user.name} />
          {!rail && (
            <span className="min-w-0 flex-1">
              <span className="block truncate text-sm font-medium text-white">{user.name}</span>
              <span className="block truncate text-xs capitalize text-rail-muted">{role?.toLowerCase().replace('_', ' ')}</span>
            </span>
          )}
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align={rail ? 'end' : 'start'} side={rail ? 'right' : 'top'} className="w-56">
        <DropdownMenuLabel className="truncate">{user.email}</DropdownMenuLabel>
        <DropdownMenuSeparator />
        <DropdownMenuItem onSelect={() => router.push('/settings')}>Account settings</DropdownMenuItem>
        <DropdownMenuItem onSelect={logout}>
          <LogOut aria-hidden />
          Sign out
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export type { NavItem };

src/components/layout/signature-notice.t:
'use client';

import * as React from 'react';
import { X } from 'lucide-react';

const SEEN_KEY = 'agencyos.signature.seen';
const VISIBLE_MS = 3000;
const EXIT_MS = 200;

/**
 * First-visit maker's mark.
 *
 * Shown once per browser, for three seconds, with a real close button. It is a polite status
 * message rather than an alert so a screen reader is not interrupted mid-page, it never takes
 * focus, and hovering or focusing it pauses the timer so nobody has to chase the X.
 * The live region stays mounted so the announcement fires when the notice appears.
 */
export function SignatureNotice() {
  const [ready, setReady] = React.useState(false);
  const [open, setOpen] = React.useState(false);
  const [closing, setClosing] = React.useState(false);
  const [paused, setPaused] = React.useState(false);
  const remaining = React.useRef(VISIBLE_MS);
  const startedAt = React.useRef<number | null>(null);

  React.useEffect(() => {
    let seen = false;
    try {
      seen = localStorage.getItem(SEEN_KEY) === '1';
    } catch {
      /* storage blocked: show it this session rather than never */
    }
    setReady(true);
    if (!seen) setOpen(true);
  }, []);

  const dismiss = React.useCallback(() => {
    setClosing(true);
    try {
      localStorage.setItem(SEEN_KEY, '1');
    } catch {
      /* ignore */
    }
    window.setTimeout(() => setOpen(false), EXIT_MS);
  }, []);

  React.useEffect(() => {
    if (!open || closing || paused) return;
    startedAt.current = Date.now();
    const timer = window.setTimeout(dismiss, remaining.current);
    return () => {
      window.clearTimeout(timer);
      if (startedAt.current !== null) {
        remaining.current = Math.max(400, remaining.current - (Date.now() - startedAt.current));
      }
    };
  }, [open, closing, paused, dismiss]);

  if (!ready) return null;

  return (
    <div
      aria-live="polite"
      role="status"
      className="pointer-events-none fixed inset-x-0 bottom-0 z-toast flex justify-center px-4 pb-[max(1rem,env(safe-area-inset-bottom))]"
    >
      {open && (
        <div
          onMouseEnter={() => setPaused(true)}
          onMouseLeave={() => setPaused(false)}
          onFocusCapture={() => setPaused(true)}
          onBlurCapture={() => setPaused(false)}
          className={[
            'pointer-events-auto flex items-center gap-3 rounded-md border border-border bg-raised py-2.5 pe-2 ps-4 shadow-3',
            'transition-[opacity,transform] duration-base ease-out motion-safe:animate-rise-in',
            closing ? 'translate-y-2 opacity-0' : 'translate-y-0 opacity-100',
          ].join(' ')}
        >
          <span aria-hidden className="h-6 w-0.5 shrink-0 rounded-full bg-accent" />
          <p className="text-sm text-ink">
            App made by{' '}
            <a
              href="https://github.com/nour-yahyaoui"
              target="_blank"
              rel="noreferrer noopener"
              className="font-semibold text-accent underline-offset-4 hover:underline"
            >
              Nour Yahyaoui
            </a>
          </p>
          <button
            type="button"
            onClick={dismiss}
            aria-label="Dismiss"
            className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-sm text-ink-muted transition-colors duration-fast hover:bg-sunken hover:text-ink"
          >
            <X className="h-4 w-4" aria-hidden />
          </button>
        </div>
      )}
    </div>
  );
}

src/components/layout/use-sidebar-resize:
'use client';

import * as React from 'react';
import {
  SIDEBAR_COOKIE,
  SIDEBAR_DEFAULT,
  SIDEBAR_MAX,
  SIDEBAR_MIN,
  SIDEBAR_SNAP,
  serializeSidebar,
  type SidebarState,
} from '@/lib/sidebar';

function persist(state: SidebarState) {
  // A cookie, not just localStorage: the server layout reads it so the first paint is already
  // the right width and the content never jumps sideways after hydration.
  document.cookie = `${SIDEBAR_COOKIE}=${serializeSidebar(state)}; path=/; max-age=31536000; samesite=lax`;
}

/**
 * Pointer + keyboard resizing for the desktop sidebar.
 *
 * During a drag we write `--sidebar-w` straight to the DOM inside a rAF and only commit React
 * state on release, so moving the mouse doesn't re-render the whole app tree per pixel.
 */
export function useSidebarResize(initial: SidebarState) {
  const [width, setWidth] = React.useState(initial.width);
  const [collapsed, setCollapsed] = React.useState(initial.collapsed);
  const [dragging, setDragging] = React.useState(false);

  const widthRef = React.useRef(width);
  const collapsedRef = React.useRef(collapsed);
  const draggingRef = React.useRef(false);
  const frame = React.useRef<number | null>(null);

  widthRef.current = width;
  collapsedRef.current = collapsed;

  const paint = React.useCallback((next: SidebarState) => {
    if (frame.current !== null) cancelAnimationFrame(frame.current);
    frame.current = requestAnimationFrame(() => {
      document.documentElement.style.setProperty('--sidebar-w', `${next.collapsed ? 72 : next.width}px`);
    });
  }, []);

  const commit = React.useCallback(
    (next: SidebarState) => {
      setWidth(next.width);
      setCollapsed(next.collapsed);
      widthRef.current = next.width;
      collapsedRef.current = next.collapsed;
      paint(next);
      persist(next);
    },
    [paint],
  );

  const toggle = React.useCallback(() => {
    commit({ width: widthRef.current, collapsed: !collapsedRef.current });
  }, [commit]);

  const reset = React.useCallback(() => commit({ width: SIDEBAR_DEFAULT, collapsed: false }), [commit]);

  const onPointerDown = React.useCallback((e: React.PointerEvent<HTMLElement>) => {
    if (e.button !== 0) return;
    draggingRef.current = true;
    setDragging(true);
    e.currentTarget.setPointerCapture(e.pointerId);
    document.body.style.userSelect = 'none';
    document.body.style.cursor = 'col-resize';
  }, []);

  const onPointerMove = React.useCallback(
    (e: React.PointerEvent<HTMLElement>) => {
      if (!draggingRef.current) return;
      const x = e.clientX;
      if (x < SIDEBAR_SNAP) {
        if (!collapsedRef.current) {
          collapsedRef.current = true;
          setCollapsed(true);
          paint({ width: widthRef.current, collapsed: true });
        }
        return;
      }
      const next = Math.min(SIDEBAR_MAX, Math.max(SIDEBAR_MIN, x));
      collapsedRef.current = false;
      widthRef.current = next;
      setCollapsed(false);
      setWidth(next);
      paint({ width: next, collapsed: false });
    },
    [paint],
  );

  const endDrag = React.useCallback(
    (e: React.PointerEvent<HTMLElement>) => {
      if (!draggingRef.current) return;
      draggingRef.current = false;
      setDragging(false);
      if (e.currentTarget.hasPointerCapture(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId);
      document.body.style.userSelect = '';
      document.body.style.cursor = '';
      persist({ width: widthRef.current, collapsed: collapsedRef.current });
    },
    [],
  );

  const onKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLElement>) => {
      const map: Record<string, () => SidebarState> = {
        ArrowLeft: () => ({ width: Math.max(SIDEBAR_MIN, widthRef.current - 16), collapsed: false }),
        ArrowRight: () => ({ width: Math.min(SIDEBAR_MAX, widthRef.current + 16), collapsed: false }),
        Home: () => ({ width: SIDEBAR_MIN, collapsed: false }),
        End: () => ({ width: SIDEBAR_MAX, collapsed: false }),
        Enter: () => ({ width: widthRef.current, collapsed: !collapsedRef.current }),
      };
      const next = map[e.key];
      if (!next) return;
      e.preventDefault();
      commit(next());
    },
    [commit],
  );

  // ⌘B / Ctrl+B toggles the rail, the shortcut every editor-trained user reaches for.
  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'b') {
        e.preventDefault();
        toggle();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [toggle]);

  React.useEffect(() => () => {
    if (frame.current !== null) cancelAnimationFrame(frame.current);
  }, []);

  return {
    width,
    collapsed,
    dragging,
    toggle,
    reset,
    setCollapsed: (value: boolean) => commit({ width: widthRef.current, collapsed: value }),
    handleProps: {
      onPointerDown,
      onPointerMove,
      onPointerUp: endDrag,
      onPointerCancel: endDrag,
      onDoubleClick: reset,
      onKeyDown,
    },
  };
}

